CREATE OR REPLACE FUNCTION public.clear_login_attempts(p_email text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $fn$ BEGIN IF coalesce(auth.role(), '') IS DISTINCT FROM 'service_role' AND LOWER(p_email) IS DISTINCT FROM LOWER(coalesce(auth.jwt()->>'email','')) THEN RAISE EXCEPTION 'clear_login_attempts: so e permitido limpar o proprio email'; END IF; DELETE FROM public.login_attempts WHERE email = LOWER(p_email); END; $fn$;
